def merge_sorted_events(streams):
    heap = []
    for i, stream in enumerate(streams):
        try:
            event = next(stream)
            heapq.heappush(heap, (event["timestamp"], i, 0, event))
        except StopIteration:
            pass

    while heap:
        timestamp, stream_index, order, event = heapq.heappop(heap)
        yield event
        try:
            next_event = next(streams[stream_index])
            heapq.heappush(heap, (next_event["timestamp"], stream_index, order + 1, next_event))
        except StopIteration:
            pass
